files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-width: 500px;
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.form {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: flex-end;
  gap: 5px;
  width: 90%;
  border: 1px solid #000;
  padding: 80px;
  background-color: #ffc802;
}

.form__field-container {
  flex-grow: 4;
  flex-basis: 300px;
}

input[type=email].form__email-field {
  width: 100%;
  height: 100%;
  background-color: transparent;
}

input[type=email].form__email-field:focus {
  outline: 2px solid #000;
  outline-offset: 0;
  background-color: #fff;
}

.form__submit-button {
  flex-grow: 1;
  border: 1px solid #000;
  padding: 10px 20px;
  font-family: inherit;
  font-weight: bold;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #6dc1fd;
  cursor: pointer;
}

.form__submit-button:hover {
  background-color: #4da1f3;
}

.form__submit-button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}
